(()=>{'use strict';const $=s=>document.querySelector(s);const STORE='history-map-journeys-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(STORE)||'{}')||{}}catch{}let current='song',stage='intro',clue=0,q=0,answer=null,choiceAnswer=null;const fresh=()=>({seen:[],choice:false,quiz:[],stamp:false});let progress={};for(const id of Object.keys(JOURNEYS)){const p=saved[id];progress[id]=p&&Array.isArray(p.seen)&&Array.isArray(p.quiz)?{seen:p.seen.filter(x=>Number.isInteger(x)&&x>=0&&x<3),choice:p.choice===true,quiz:p.quiz.filter(x=>Number.isInteger(x)&&x>=0&&x<3),stamp:p.stamp===true}:fresh()}const d=()=>JOURNEYS[current],p=()=>progress[current];function save(){try{localStorage.setItem(STORE,JSON.stringify(progress))}catch{}updatePassport()}function updatePassport(){$('#stampCount').textContent=Object.values(progress).filter(x=>x.stamp).length+' / 3';$('#stamps').innerHTML=Object.entries(JOURNEYS).map(([id,j])=>`<div class="stamp ${progress[id].stamp?'earned':''}">${id==='song'?'宋 · 城市':id==='qin'?'秦 · 整合':'唐 · 旅行'}<br>${progress[id].stamp?'旅程完成 ✓':'等待你的足跡'}</div>`).join('')}function renderEras(){ $('#eras').innerHTML=ERAS.map((e,i)=>`<button data-era="${i}" class="${i===d().era?'active':''}" aria-pressed="${i===d().era}">${e.title}<small>${e.date}</small></button>`).join('');document.querySelectorAll('[data-era]').forEach(b=>b.onclick=()=>{const e=ERAS[+b.dataset.era];$('#eraDetail').hidden=false;$('#eraInfo').setAttribute('aria-expanded','true');$('#eraDetail').innerHTML=`<strong>${e.title} · ${e.date}</strong>${e.text}${e.journey?'':'<p>本區為年代概覽；完整互動旅程目前提供秦、唐、宋三課。</p>'}`;if(e.journey)select(e.journey,false)})}function select(id,hide=true){current=id;stage='intro';answer=null;choiceAnswer=null;q=0;if(hide)$('#eraDetail').hidden=true;render();}function render(){renderEras();$('#journeyTitle').textContent=d().title;$('#journeySubtitle').textContent=d().subtitle;document.querySelectorAll('[data-journey]').forEach(b=>{b.classList.toggle('active',b.dataset.journey===current);b.setAttribute('aria-pressed',b.dataset.journey===current)});renderMap();renderStory();renderTeacher();$('#sources').innerHTML='<ol>'+d().sources.map(s=>`<li><a href="${s[1]}" target="_blank" rel="noopener noreferrer">${s[0]} ↗</a><br>${s[2]}</li>`).join('')+'</ol>';updatePassport()}
function renderMap(){const j=d();const route=current==='song'?'M491 296 Q476 247 440 238 Q422 220 405 201':current==='qin'?'M308 199 L346 216 Q377 257 370 307':'M391 207 L334 217 Q248 173 126 137';$('#map').innerHTML=`<svg viewBox="0 0 640 390" role="img" aria-labelledby="mapSvgTitle mapSvgDesc"><title id="mapSvgTitle">${j.title}地理示意</title><desc id="mapSvgDesc">上北下南。${j.clues.map((c,i)=>`${i+1}，${c.name}，${c.label}`).join('；')}。可使用地圖下方文字按鈕讀取相同線索。</desc><defs><pattern id="dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#bac7b0" opacity=".45"/></pattern><filter id="shadow"><feDropShadow dx="0" dy="3" stdDeviation="3" flood-opacity=".12"/></filter></defs><rect width="640" height="390" fill="#e9ede1"/><rect width="640" height="390" fill="url(#dots)"/><path d="M565 0 L640 0 640 390 490 390 499 357 531 338 533 308 548 295 552 266 572 243 577 211 560 184 570 157 549 137 565 111 550 83Z" fill="#d2e3de"/><path d="M550 83 L565 111 549 137 570 157 560 184 577 211 572 243 552 266 548 295 533 308 531 338 499 357 490 390" fill="none" stroke="#a6bfb1" stroke-width="2"/><g fill="none" stroke="#b5c5a4" stroke-width="1.5" opacity=".6"><path d="M32 193 l19 -25 15 18 24 -35 21 28 18 -19 34 39 M65 213 l24 -29 21 23 29 -25 25 27 M173 290 l24 -27 26 29 22 -38 25 30 M207 90 l18 -25 17 22 25 -16 24 28 M282 324 l20 -24 15 22 24 -14 15 21"/><path d="M25 250 Q130 224 185 255 T311 279 M46 263 Q134 241 180 268 T293 294"/></g><g class="rivers-layer" fill="none" stroke="#95b9ac" stroke-width="4" stroke-linecap="round"><path d="M195 190 Q209 158 237 175 L253 100 Q275 86 301 105 L305 169 Q330 190 375 184 Q417 179 454 187 L530 197"/><path d="M178 263 Q204 310 260 285 T334 286 Q365 265 396 288 T491 296 L547 279"/></g><g fill="#718b7c" font-size="11" letter-spacing="4"><text x="246" y="66">黃土高原</text><text x="105" y="284">青藏高原方向</text><text x="558" y="333" transform="rotate(-15 558 333)">海域</text><text x="415" y="172" class="rivers-layer">黃河示意</text><text x="423" y="323" class="rivers-layer">長江示意</text></g><path class="routes-layer" d="${route}" fill="none" stroke="#bd5d39" stroke-width="2.5" stroke-dasharray="5 5" opacity=".8"/><g transform="translate(582 36)" fill="#566f5f"><path d="M0 27 L8 0 16 27 8 20Z"/><text x="8" y="-7" text-anchor="middle" font-size="10">北 N</text></g><text x="28" y="33" fill="#536d5c" font-size="10" letter-spacing="2">${j.period} · 地理聯繫示意</text>${j.clues.map((c,i)=>`<g class="map-point" tabindex="0" role="button" data-clue="${i}" aria-label="線索${i+1}：${c.name}，${c.label}" transform="translate(${c.x} ${c.y})"><circle r="15" fill="${p().seen.includes(i)?'#315a47':'#bd5d39'}" stroke="#f7f5ed" stroke-width="3" filter="url(#shadow)"/><text text-anchor="middle" y="5" fill="white" font-size="12" font-weight="700">${i+1}</text><text x="${current==='qin'&&i===0?-23:21}" y="${current==='qin'&&i===0?-10:5}" text-anchor="${current==='qin'&&i===0?'end':'start'}" fill="#233d34" font-weight="600" font-size="12" stroke="#e9ede1" stroke-width="4" paint-order="stroke">${c.name}</text></g>`).join('')}<g transform="translate(29 323)"><rect width="130" height="40" rx="3" fill="#f7f5ed" opacity=".8"/><text x="10" y="16" font-size="10" fill="#657969">● 城市／區域節點</text><text x="10" y="31" font-size="9" fill="#657969">虛線為聯繫，非精確古道</text></g></svg>`;$('#mapText').innerHTML=j.clues.map((c,i)=>`<button data-clue="${i}" class="${p().seen.includes(i)?'seen':''}">${p().seen.includes(i)?'✓':i+1} ${c.name}</button>`).join('');document.querySelectorAll('[data-clue]').forEach(b=>{b.onclick=()=>openClue(+b.dataset.clue);b.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&b.tagName.toLowerCase()==='g'){e.preventDefault();openClue(+b.dataset.clue)}}});layers();if(window.historyGlobe)window.historyGlobe.update(current,p().seen,openClue)}
function layers(){if(window.historyGlobe)window.historyGlobe.layers();document.querySelectorAll('.routes-layer').forEach(e=>e.style.display=$('#routes').checked?'':'none');document.querySelectorAll('.rivers-layer').forEach(e=>e.style.display=$('#rivers').checked?'':'none')}
function art(){return `<svg class="scene-art" viewBox="0 0 360 95" aria-hidden="true"><g fill="none" stroke="#6b8066" stroke-width="1.5"><path d="M0 84 H360 M30 80 V35 H100 V80 M22 35 L65 13 108 35Z M43 49 H55 V69 H43Z M73 49 H86 V69 H73Z M190 80 V40 H260 V80 M180 40 L224 20 272 40Z M207 80 V55 H237 V80 M120 77 Q147 58 173 77 M130 77 Q147 65 164 77"/><path d="M281 77 Q305 62 341 77 L332 88 H291Z M314 76 V25 L338 62 H314 M299 76 V42 L281 65 H299"/><path d="M3 91 Q35 85 69 91 T137 91 T205 91 T273 91 T341 91" stroke="#9ab5a3"/></g><circle cx="149" cy="25" r="12" fill="#d9a778" opacity=".6"/></svg>`}
function top(label,index){return `<div class="step-label"><span>${label}</span><span>${index} / 4</span></div><div class="progress">${[1,2,3,4].map(i=>`<i class="${i<=index?'done':''}"></i>`).join('')}</div>`}
function renderStory(){let html='';if(stage==='intro'){html=top('情境 · 收到一張旅行邀請',1)+`<span class="tag">教學虛構角色</span><h3 id="storyTitle">${d().role}</h3>${art()}<p>${d().intro}</p><div class="clue-note">學習節奏：情境 2 分鐘 → 線索 5 分鐘 → 選擇 3 分鐘 → 測驗 3 分鐘。${current==='song'?'你人在開封；地圖追查的是食物供應，不是一天走遍各地。':''}</div><button class="primary" id="start">出發，尋找第一則線索 →</button>`}else if(stage==='clue'){const c=d().clues[clue];html=top('觀察 · 已收集 '+p().seen.length+' / 3 則線索',2)+`<span class="tag">${c.tag}</span><h3 id="storyTitle">${c.title}</h3><p>${c.text}</p><div class="clue-note"><strong>證據提醒</strong><br>${c.evidence}</div><a class="source-link" href="${d().sources[c.source][1]}" target="_blank" rel="noopener noreferrer">閱讀來源：${d().sources[c.source][0]} ↗</a><button class="primary" id="nextClue">${p().seen.length===3?'線索齊了，做出你的選擇 →':'尋找下一則線索 →'}</button><br><button class="secondary" id="backIntro">回到情境</button>`}else if(stage==='choice'){const c=d().choice;html=top('推論 · 用證據做選擇',3)+`<span class="tag">不是猜，而是找依據</span><h3 id="storyTitle">${c.question}</h3><div class="options">${c.options.map((v,i)=>`<button class="option ${choiceAnswer===i?'selected':''}" data-choice="${i}" aria-pressed="${choiceAnswer===i}">${String.fromCharCode(65+i)}. ${v}</button>`).join('')}</div>${choiceAnswer!==null?`<div class="feedback" role="status">${choiceAnswer===c.answer?'✓ 這個推論有證據支持。':'再比較一次：這個說法忽略或超出了線索。'}<br>${c.explanation}</div>`:''}<button class="primary" id="toQuiz" ${choiceAnswer!==c.answer?'disabled':''}>前往三題小測驗 →</button><br><button class="secondary" id="review">重新查看線索</button>`}else if(stage==='quiz'){const t=d().quiz[q];html=top('回顧 · 旅人小測驗 '+(q+1)+' / 3',4)+`<h3 id="storyTitle">${t.q}</h3><div class="options">${t.options.map((v,i)=>`<button class="option ${answer===i?'selected':''}" data-answer="${i}" aria-pressed="${answer===i}">${String.fromCharCode(65+i)}. ${v}</button>`).join('')}</div>${answer!==null?`<div class="feedback" role="status">${answer===t.answer?'✓ 答對了！':'還差一點，再試一次。'}<br>${t.why}</div>`:''}<button class="primary" id="nextQ" ${answer!==t.answer?'disabled':''}>${q===2?'完成旅程，蓋上印章 →':'下一題 →'}</button>`}else{html=top('完成 · 帶著新問題回來',4)+`<span class="tag">旅人印章已收集 ✓</span><h3 id="storyTitle">你不只記住年代，<br>也看見了生活。</h3><p>${d().choice.explanation}</p><div class="clue-note"><strong>留給你的問題</strong><br>${d().discussion}</div><button class="primary" id="openPassport">打開我的護照 →</button><br><button class="secondary" id="restart">再走一次這段旅程</button>`}$('#story').innerHTML=html;const on=(s,f)=>{if($(s))$(s).onclick=f};on('#start',()=>openClue(0));on('#nextClue',()=>{if(p().seen.length===3){stage='choice';choiceAnswer=null;renderStory()}else openClue([0,1,2].find(i=>!p().seen.includes(i)))});on('#backIntro',()=>{stage='intro';renderStory()});document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{choiceAnswer=+b.dataset.choice;if(choiceAnswer===d().choice.answer){p().choice=true;save()}renderStory()});on('#toQuiz',()=>{stage='quiz';q=0;answer=null;renderStory()});on('#review',()=>openClue(0));document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{answer=+b.dataset.answer;if(answer===d().quiz[q].answer&&!p().quiz.includes(q)){p().quiz.push(q);save()}renderStory()});on('#nextQ',()=>{if(q<2){q++;answer=null}else{p().stamp=p().seen.length===3&&p().choice&&p().quiz.length===3;save();stage='done'}renderStory()});on('#openPassport',()=>$('#passport').showModal());on('#restart',()=>{stage='intro';renderStory()});}
function openClue(i){clue=i;stage='clue';if(!p().seen.includes(i))p().seen.push(i);save();renderMap();renderStory();if(innerWidth<681)$('#story').scrollIntoView({behavior:'auto',block:'start'});$('#storyTitle').tabIndex=-1;$('#storyTitle').focus({preventScroll:true})}
function renderTeacher(){$('#teacherContent').innerHTML=`<div class="teacher-grid"><div><h3>學習目標</h3><p>${d().objective}</p><h3>15 分鐘帶課節奏</h3><ol><li>2 分鐘：閱讀虛構情境，先提出假說。</li><li>5 分鐘：小組各讀一則線索，區分觀察與推論。</li><li>3 分鐘：選擇答案，說出至少兩則依據。</li><li>3 分鐘：個別測驗，回看解釋。</li><li>2 分鐘：全班討論，提出尚缺的證據。</li></ol></div><div><h3>討論提問</h3><p>${d().discussion}</p><details><summary>顯示答案與教學提醒</summary><p>證據選擇：${String.fromCharCode(65+d().choice.answer)}。${d().choice.explanation}</p><ol>${d().quiz.map(t=>`<li>${String.fromCharCode(65+t.answer)}：${t.why}</li>`).join('')}</ol><p>鼓勵學生說「史料支持……，但還不能證明……」。年代概覽是教學分組，不表示政權線性接替。</p></details></div></div>`}
document.querySelectorAll('[data-journey]').forEach(b=>b.onclick=()=>select(b.dataset.journey));$('#routes').onchange=layers;$('#rivers').onchange=layers;$('#eraInfo').onclick=()=>{const el=$('#eraDetail');el.hidden=!el.hidden;$('#eraInfo').setAttribute('aria-expanded',!el.hidden);el.innerHTML='<strong>同一時間，不只一個政權。</strong>'+ERAS[d().era].text+'<p>點選時代可查看概覽；有完整旅程的秦、唐、宋會同步切換。這裡的年份是政權／時段索引，不是精確疆界。</p>'};$('#teacherToggle').onclick=()=>{const el=$('#teacher');el.hidden=!el.hidden;$('#teacherToggle').setAttribute('aria-pressed',!el.hidden);if(!el.hidden)el.scrollIntoView({behavior:'auto'})};$('#largeToggle').onclick=()=>{document.body.classList.toggle('large');$('#largeToggle').setAttribute('aria-pressed',document.body.classList.contains('large'))};$('#passportToggle').onclick=()=>$('#passport').showModal();$('#reset').onclick=()=>$('#resetConfirm').hidden=false;$('#resetNo').onclick=()=>$('#resetConfirm').hidden=true;$('#resetYes').onclick=()=>{for(const id of Object.keys(JOURNEYS))progress[id]=fresh();save();$('#resetConfirm').hidden=true;$('#passport').close();select(current)};window.historyMapRefresh=()=>{if(window.historyGlobe)window.historyGlobe.update(current,p().seen,openClue)};render();})();
